import{_ as a,o as r,c as e,ag as d}from"./chunks/framework.Cp9o0o35.js";const p=JSON.parse('{"title":"bridge-lite とは","description":"","frontmatter":{},"headers":[],"relativePath":"ja/introduction.md","filePath":"ja/introduction.md"}'),o={name:"ja/introduction.md"};function i(n,t,l,h,s,c){return r(),e("div",null,[...t[0]||(t[0]=[d('<h1 id="bridge-lite-とは" tabindex="-1">bridge-lite とは <a class="header-anchor" href="#bridge-lite-とは" aria-label="Permalink to &quot;bridge-lite とは&quot;">​</a></h1><p>bridge-lite は、RAW+JPG 同時撮影をするフォトグラファーのための<strong>軽量画像セレクトビュワー</strong>です。</p><p>「撮って出し（JPEG）」「RAW」「現像済み」が入り混じる撮影後のフォルダの中で、どのファイルを現像したか、どんな評価がついているかを把握する——その「現在地の確認」を担います。</p><h2 id="何をするアプリか" tabindex="-1">何をするアプリか <a class="header-anchor" href="#何をするアプリか" aria-label="Permalink to &quot;何をするアプリか&quot;">​</a></h2><p>bridge-lite がやることは三つだけです。</p><ul><li><strong>見る</strong> — サムネイルグリッドで大量の写真を素早くスクロール</li><li><strong>評価する</strong> — 0〜5 星の XMP レーティングをキーボードで付ける</li><li><strong>比べる</strong> — 撮って出し・RAW・現像済みを一枚として行き来する</li></ul><p>現像・レタッチ・書き出しは行いません。それらはすでにあなたが使っている Lightroom や Capture One に委ねます。</p><h2 id="何をしないか" tabindex="-1">何をしないか <a class="header-anchor" href="#何をしないか" aria-label="Permalink to &quot;何をしないか&quot;">​</a></h2><table tabindex="0"><thead><tr><th>しないこと</th><th>担うツール</th></tr></thead><tbody><tr><td>現像・色補正</td><td>Lightroom / Capture One / Darkroom</td></tr><tr><td>書き出し・リサイズ</td><td>現像ツール</td></tr><tr><td>カタログ管理</td><td>現像ツール</td></tr><tr><td>クラウド共有</td><td>スコープ外</td></tr></tbody></table><h2 id="ファイルは変更しない" tabindex="-1">ファイルは変更しない <a class="header-anchor" href="#ファイルは変更しない" aria-label="Permalink to &quot;ファイルは変更しない&quot;">​</a></h2><p>閲覧・スクロール・フィルタリングのいかなる操作においても、元ファイルのバイト列・タイムスタンプ・パーミッションは一切変更しません。メモリカードやネットワークドライブからも安心して使えます。</p><p>レーティング情報は XMP サイドカーファイルに書き込まれます。RAW ファイル本体は変更しません。</p><h2 id="動作環境" tabindex="-1">動作環境 <a class="header-anchor" href="#動作環境" aria-label="Permalink to &quot;動作環境&quot;">​</a></h2><table tabindex="0"><thead><tr><th>項目</th><th>要件</th></tr></thead><tbody><tr><td>OS</td><td>macOS 14 Sonoma 以降</td></tr><tr><td>チップ</td><td>Apple Silicon（M1 以降）</td></tr><tr><td>価格</td><td>無料（MIT ライセンス）</td></tr></tbody></table>',14)])])}const u=a(o,[["render",i]]);export{p as __pageData,u as default};
